BEGIN;SET LOCAL statement_timeout='30s';CREATE TEMP TABLE block_workflow_before ON COMMIT DROP AS SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'acl',a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY c.relname) FROM pg_class c WHERE c.oid IN ('public.auto_blocks'::regclass,'public.auto_workflows'::regclass)),
 'other_role_column_permissions',(SELECT md5(string_agg(r.rolname||':'||c.relname||':'||a.attname||':'||p.priv||':'||has_column_privilege(r.oid,c.oid,a.attnum,p.priv)::text,',' ORDER BY r.rolname,c.relname,a.attnum,p.priv)) FROM pg_roles r CROSS JOIN pg_class c JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('REFERENCES')) p(priv) WHERE c.oid IN ('public.auto_blocks'::regclass,'public.auto_workflows'::regclass) AND r.rolname<>'aka_agent_desktop'),
